// Construir lista de leads contactados por asesor
const calls  = $('HubSpot - Traer llamadas').first().json.results || [];
const owners = $('HubSpot - Propietarios').first().json.results  || [];

const ownerMap = {};
for (const o of owners) {
  ownerMap[o.id] = `${o.firstName} ${o.lastName}`.trim();
}

// De-duplicar: un contacto = un lead, independiente de cuántas llamadas
const leadsMap = {};

for (const call of calls) {
  const ownerId = call.properties.hubspot_owner_id;
  const asesor  = ownerMap[ownerId] || `Asesor ${ownerId}`;
  const assocs  = call.associations?.contacts?.results || [];

  for (const contact of assocs) {
    const key = `${ownerId}_${contact.id}`;
    if (!leadsMap[key]) {
      leadsMap[key] = {
        id:             `L${contact.id}`,
        nombre:         `Contacto ${contact.id}`, // se enriquece abajo si tienes más datos
        asesorId:       ownerId,
        asesor:         asesor,
        ultimaLlamada:  call.properties.hs_timestamp,
        totalLlamadas:  1,
        estadoNegocio:  'Contactado',
      };
    } else {
      leadsMap[key].totalLlamadas++;
      // Mantener la llamada más reciente
      if (new Date(call.properties.hs_timestamp) > new Date(leadsMap[key].ultimaLlamada)) {
        leadsMap[key].ultimaLlamada = call.properties.hs_timestamp;
      }
    }
  }
}

const leads = Object.values(leadsMap)
  .sort((a, b) => new Date(b.ultimaLlamada) - new Date(a.ultimaLlamada));

return leads.map(l => ({ json: l }));
